package org.mcrf.client;
import org.junit.Test;
import org.json.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.Assert.*;
public class CarrierProfileTest {
    static final String KEY="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
    @Test public void olcUriMatchesOfficialConvention()throws Exception{ServerImport.Server entry=ServerImport.read("olcrtc://jitsi?datachannel@https%3A%2F%2Fmeet.example.com%2Froom#"+KEY+"$My%20server").get(0);assertEquals("My server",entry.name);assertEquals("https://meet.example.com/room",entry.carrier.getString("room"));assertTrue(entry.needsEngine());JSONObject config=ServerImport.build(List.of(entry),entry.id,false,60,50,"Cloudflare");assertEquals(ServerImport.tag(entry),config.getJSONObject("mcrf_carrier").getString("outbound_tag"));assertEquals("socks",config.getJSONArray("outbounds").getJSONObject(1).getString("type"));}
    @Test public void olcTransportOptions()throws Exception{ServerImport.Server entry=ServerImport.read("olcrtc://telemost?videochannel<video-w=1080&video-h=1080&video-fps=30&video-codec=tile>@room#"+KEY).get(0);assertEquals("tile",entry.carrier.getJSONObject("options").getString("video-codec"));}
    @Test public void dnsttDohAndCredentials()throws Exception{String link="dnstt://"+KEY+"@t.example.com?doh="+URLEncoder.encode("https://dns.example/dns-query",StandardCharsets.UTF_8)+"&username=alice&password=pass%2Bword#DNS";ServerImport.Server e=ServerImport.read(link).get(0);assertEquals("pass+word",e.carrier.getString("password"));assertEquals("DNS",e.name);assertEquals("https://dns.example/dns-query",e.carrier.getString("doh"));}
    @Test public void nativeJsonRoundTrip()throws Exception{JSONObject c=new JSONObject().put("type","dnstt").put("key",KEY).put("domain","t.example.com").put("udp","1.1.1.1:53");ServerImport.Server e=ServerImport.read(c.toString()).get(0);assertNull(e.configuration);assertEquals("1.1.1.1:53",e.carrier.getString("udp"));}
    @Test public void rejectInvalidProfilesWithoutSecrets()throws Exception{for(String link:new String[]{"dnstt://private-key@t.example.com","dnstt://"+KEY+"@t.example.com?doh=http%3A%2F%2Fdns.example","dnstt://"+KEY+"@t.example.com?dot=dns.example:853&udp=1.1.1.1:53","olcrtc://telemost?datachannel@room#"+KEY,"olcrtc://jitsi?videochannel<video-fps=0>@meet.example/room#"+KEY}){try{ServerImport.read(link);fail(link.substring(0,9));}catch(IllegalArgumentException expected){assertFalse(expected.getMessage().contains(KEY));assertFalse(expected.getMessage().contains("private-key"));}}}
    @Test public void stableTagsSurviveReordering()throws Exception{List<ServerImport.Server> e=ServerImport.read(ServerImportTest.cases().getJSONObject(0).getString("link")+"\n"+ServerImportTest.cases().getJSONObject(1).getString("link"));String tag=ServerImport.build(e,e.get(0).id,false,60,50,"Cloudflare").getJSONObject("route").getString("final");Collections.reverse(e);assertEquals(tag,ServerImport.build(e,e.get(1).id,false,60,50,"Cloudflare").getJSONObject("route").getString("final"));}
    @Test public void trafficCounterAndReset(){TrafficState.reset("Fixture");TrafficState.update(100,200,1000);TrafficState.update(2100,6200,3000);assertEquals(1000,TrafficState.current.upload);assertEquals(3000,TrafficState.current.download);TrafficState.server("Selected");assertEquals(6200,TrafficState.current.received);TrafficState.stop();assertEquals(0,TrafficState.current.download);assertEquals("Selected",TrafficState.current.server);TrafficState.update(2,3,4000);assertEquals(0,TrafficState.current.download);}
    @Test public void authorizationIsRedacted(){assertFalse(ClientEvents.redact("Authorization: Bearer hiddenToken").contains("hiddenToken"));assertFalse(ClientEvents.redact("authorization=Basic encodedSecret").contains("encodedSecret"));assertFalse(ClientEvents.redact("dnstt://secret@domain").contains("secret@"));}
}
